package io.github.foodjournal.telegram;
import io.github.foodjournal.config.BotProperties; import io.github.foodjournal.messaging.*; import io.github.foodjournal.service.UpdateService; import java.util.*; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.http.*; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/telegram") public class TelegramWebhookController {
 private final BotProperties props; private final UpdateService legacy; private final MessagingIngressService ingress;
 public TelegramWebhookController(BotProperties p,UpdateService s){props=p;legacy=s;ingress=null;}
 @Autowired public TelegramWebhookController(BotProperties p, MessagingIngressService ingress){props=p;legacy=null;this.ingress=ingress;}
 @PostMapping("/webhook") public ResponseEntity<Void> webhook(@RequestHeader(value="X-Telegram-Bot-Api-Secret-Token",required=false) String secret,@RequestBody TelegramUpdate update){ if(!props.webhookSecret().equals(secret)) return ResponseEntity.status(HttpStatus.FORBIDDEN).build(); if(ingress==null){legacy.enqueue(update);return ResponseEntity.ok().build();} TelegramMessage message=update==null?null:update.message(); if(message==null||message.from()==null||message.chat()==null||update.update_id()==null)return ResponseEntity.ok().build(); List<Attachment> attachments=new ArrayList<>(); if(message.voice()!=null)attachments.add(new Attachment(Attachment.Kind.VOICE,message.voice().file_id(),message.voice().mime_type(),null)); if(message.photo()!=null&&!message.photo().isEmpty()){TelegramPhoto photo=message.photo().getLast();attachments.add(new Attachment(Attachment.Kind.PHOTO,photo.file_id(),"image/jpeg",null));} if(message.document()!=null)attachments.add(new Attachment(Attachment.Kind.DOCUMENT,message.document().file_id(),message.document().mime_type(),message.document().file_name())); ingress.accept(new InboundMessage("telegram",String.valueOf(update.update_id()),String.valueOf(message.from().id()),String.valueOf(message.chat().id()),message.from().first_name(),message.from().language_code(),message.text(),message.caption(),attachments)); return ResponseEntity.ok().build(); }
}
